use rk3588_boot_support::{DelayUs,Mmio32};use crate::stage8::PcieBootConfig;use crate::stage14::HotResetWait;use crate::stage15::{EndpointBootError,EndpointBootReport};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum EndpointTerminalState{HotResetObserved,ForcedFromL2}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct EndpointTerminalReport{pub boot:EndpointBootReport,pub terminal:EndpointTerminalState}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum EndpointTerminalError{Boot(EndpointBootError),HotResetTimeout}
pub fn run_endpoint_to_terminal<I:Mmio32+DelayUs>(io:&mut I,cfg:PcieBootConfig,cfg_base:u64,ctrl_base:u64,vendor:u16,device:u16,link_samples:u32)->Result<EndpointTerminalReport,EndpointTerminalError>{let boot=crate::stage15::run_endpoint_boot_flow(io,cfg,cfg_base,ctrl_base,vendor,device,link_samples).map_err(EndpointTerminalError::Boot)?;let terminal=match boot.hot_reset{HotResetWait::Observed=>EndpointTerminalState::HotResetObserved,HotResetWait::ForcedFromL2=>EndpointTerminalState::ForcedFromL2,HotResetWait::Timeout=>return Err(EndpointTerminalError::HotResetTimeout)};Ok(EndpointTerminalReport{boot,terminal})}
#[cfg(test)]mod tests{use super::*;struct M;impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{0xFD5B8904=>0xF,768=>0x30000,16=>4,_=>0}}fn write32(&mut self,_:u64,_:u32){}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}#[test]fn terminal(){let mut m=M;let cfg=PcieBootConfig{phy_mode:0,generation:3,lanes:1};let r=run_endpoint_to_terminal(&mut m,cfg,0,0,0x1d87,0x356a,2).unwrap();assert_eq!(r.terminal,EndpointTerminalState::HotResetObserved);}}
